SELECT DISTINCT ?graph ?subject ?predicate ?object
WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_058f4b6abd0b757a>
    <urn:graphragprov:unit:u_674424a03e1a0fb5>
    <urn:graphragprov:unit:u_7941ba420f6107fe>
    <urn:graphragprov:unit:u_b2b2839417fb6bd0>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
    FILTER(isIRI(?subject))
  }
}
ORDER BY ?graph ?subject ?predicate ?object
